-- CMS-driven configuration for Agent Pre-Visit and Visit forms.

create table if not exists public.form_fields (
  id bigint generated by default as identity primary key,
  form_key text not null check (form_key in ('pre_visit','visit')),
  field_key text not null,
  label_en text not null,
  label_id text not null,
  field_type text not null check (field_type in ('text','textarea','select','radio','checkbox','date','datetime','number')),
  required boolean not null default false,
  visible boolean not null default true,
  sort_order integer not null default 0,
  placeholder_en text,
  placeholder_id text,
  help_text_en text,
  help_text_id text,
  options jsonb not null default '[]'::jsonb,
  system_field boolean not null default true,
  protected boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique(form_key, field_key)
);

alter table public.form_fields enable row level security;
revoke all on table public.form_fields from anon;
grant select, insert, update, delete on table public.form_fields to authenticated, service_role;
grant usage, select on sequence public.form_fields_id_seq to authenticated, service_role;

drop policy if exists "form_fields_authenticated_read" on public.form_fields;
create policy "form_fields_authenticated_read"
on public.form_fields for select to authenticated using (true);

drop policy if exists "form_fields_superadmin_write" on public.form_fields;
create policy "form_fields_superadmin_write"
on public.form_fields for all to authenticated
using (
  exists (
    select 1 from public.agents a
    where lower(a.email) = lower(auth.jwt()->>'email')
      and a.active
      and a.role = 'superadmin'
  )
)
with check (
  exists (
    select 1 from public.agents a
    where lower(a.email) = lower(auth.jwt()->>'email')
      and a.active
      and a.role = 'superadmin'
  )
);

alter table public.pre_visits add column if not exists extra_data jsonb not null default '{}'::jsonb;
alter table public.visits add column if not exists extra_data jsonb not null default '{}'::jsonb;

